import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # Days in each month for years 2013, 2014, 2015 (non-leap years)
    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 36, 31]

    def is_valid_date(d, m, y):
        if y < 2013 or y > 2015:
            return False
        if m < 1 or m > 12:
            return False
        if d < 1 or d > days_in_month[m]:
            return False
        return True

    count = {}

    i = 0
    while i <= n - 10:
        # Check if we have a potential date starting at i
        # Format: dd-mm-yyyy -> indices: 0,1 - 3,4 - 6,7,8,9 relative to start
        if i + 10 <= n:
            part1 = s[i:i+2]
            part2 = s[i+2:i+3]
            part3 = s[i+3:i+4]
            part4 = s[i+4:i+10]

            # Check separators
            if s[i+2] == '-' and s[i+4] == '-':
                # Check if parts are digits
                if part1.isdigit() and part2.isdigit() and part4.isdigit():
                    d = int(part1)
                    m = int(part2)
                    y = int(part4)

                    if is_valid_date(d, m, y):
                        date_str = f"{d:02d}-{m:02d}-{y}"
                        count[date_str] = count.get(date_str, 0) + 1

        i += 1

    max_count = -1
    result_date = ""

    for date_str, cnt in count.items():
        if cnt > max_count:
            max_count = cnt
            result_date = date_str

    print(result_date)

if __name__ == "__main__":
    solve()
